const room=window.room={face:false,running:false,rewind:0,calm:0,time:43080,sound:false,gentle:matchMedia('(prefers-reduced-motion: reduce)').matches};
const el=id=>document.getElementById(id);
let audio,master,hiss,filter;
function tone(f,d=.3,v=.1,end=f){if(!audio||!room.sound)return;const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(master);o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(end,audio.currentTime+d);g.gain.setValueAtTime(v,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.start();o.stop(audio.currentTime+d)}
el('sound').onclick=async()=>{if(!audio){audio=new AudioContext();master=audio.createGain();master.connect(audio.destination);const b=audio.createBuffer(1,audio.sampleRate*2,audio.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;const s=audio.createBufferSource();s.buffer=b;s.loop=true;filter=audio.createBiquadFilter();filter.type='lowpass';hiss=audio.createGain();hiss.gain.value=0;s.connect(filter);filter.connect(hiss);hiss.connect(master);s.start()}await audio.resume();room.sound=!room.sound;master.gain.setTargetAtTime(room.sound?.3:0,audio.currentTime,.1);el('sound').setAttribute('aria-pressed',room.sound)};
el('gentle').setAttribute('aria-pressed',room.gentle);el('gentle').onclick=()=>{room.gentle=!room.gentle;el('gentle').setAttribute('aria-pressed',room.gentle)};
el('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.().catch(()=>{})};
new p5(p=>{let field,parts=[],palette=[],phase=0,seed=0,t=0,lastTick=-1,swipeStart;const bayer=[0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5];const roman=['XII','I','II','III','IV','V','VI','VII','VIII','IX','X','XI'];
function regenerate(){seed=Math.random()*9999;p.noiseSeed(seed);p.noiseDetail(2,.45);phase=p.random(p.TWO_PI);palette=Array.from({length:5},()=>[p.random(145,245),p.random(145,245),p.random(165,255)]);parts=[];let mode=p.floor(p.random(4)),count=mode===3?19:p.floor(p.random(7,13));for(let i=0;i<count;i++){let a=i*2.399+phase,r=Math.sqrt(i/count)*.39,x,y,size;if(mode===0){x=.5+Math.cos(a)*r;y=.5+Math.sin(a)*r;size=i===0?.24:p.random(.055,.16)}else if(mode===1){x=.15+.7*i/(count-1);y=.5+Math.sin(i*.9+phase)*.23;size=p.random(.08,.22)}else if(mode===2){x=.5+Math.cos(a)*p.random(.12,.36);y=.5+Math.sin(a)*p.random(.12,.35);size=i<2?.27:p.random(.06,.14)}else{x=p.random(.08,.92);y=p.random(.08,.92);size=p.random(.04,.17)}parts.push({x,y,size,clock:i<3||p.random()>.55,spin:p.random(p.TWO_PI),direction:i%2?1:-1,teeth:p.floor(p.random(16,38)),color:palette[i%5],detail:p.floor(p.random(2,5))})}}window.regenerateArt=regenerate;
p.setup=()=>{p.createCanvas(innerWidth,innerHeight).parent('art');p.pixelDensity(1);p.frameRate(30);makeField();regenerate();el('shuffle').onclick=regenerate;el('art').addEventListener('pointerdown',e=>swipeStart={x:e.clientX,y:e.clientY,t:performance.now()});el('art').addEventListener('pointerup',e=>{if(swipeStart&&e.clientX-swipeStart.x>70&&Math.abs(e.clientY-swipeStart.y)<120&&performance.now()-swipeStart.t<1000)regenerate();swipeStart=null});addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();regenerate()}})};
function makeField(){const w=Math.min(650,Math.round(innerWidth*.55)),h=Math.round(w*innerHeight/innerWidth);field=p.createImage(w,h)}p.windowResized=()=>{p.resizeCanvas(innerWidth,innerHeight);makeField()};
function gear(r,teeth,rotation,detail=3){p.push();p.rotate(rotation);p.beginShape();for(let j=0;j<teeth*4;j++){let a=j*p.TWO_PI/(teeth*4),rr=r*(j%4<2?1:.92);p.vertex(Math.cos(a)*rr,Math.sin(a)*rr)}p.endShape(p.CLOSE);p.circle(0,0,r*1.76);p.circle(0,0,r*.4);p.circle(0,0,r*.27);for(let j=0;j<detail+3;j++){p.push();p.rotate(j*p.TWO_PI/(detail+3));p.beginShape();p.vertex(r*.24,-r*.04);p.vertex(r*.8,-r*.075);p.vertex(r*.8,r*.075);p.vertex(r*.24,r*.04);p.endShape(p.CLOSE);p.pop()}p.pop()}
function hand(a,len,w){p.push();p.rotate(a);p.beginShape();p.vertex(0,-len);p.vertex(w,-len*.25);p.vertex(w*.3,0);p.vertex(w*.6,len*.18);p.vertex(0,len*.25);p.vertex(-w*.6,len*.18);p.vertex(-w*.3,0);p.vertex(-w,-len*.25);p.endShape(p.CLOSE);p.pop()}
function dial(q){p.push();p.translate(q.x*p.width,q.y*p.height);let r=q.size*Math.min(p.width,p.height);p.scale(r/200);p.stroke(...q.color,64);p.strokeWeight(Math.max(.9,1.5*200/r));p.noFill();const rot=q.spin+room.time*.015*q.direction;if(!q.clock){gear(200,q.teeth,rot,q.detail);p.pop();return}for(const rr of [200,195,188,174,169,145,140,94,88])p.circle(0,0,rr*2);for(let i=0;i<120;i++){p.push();p.rotate(i*p.TWO_PI/120);p.line(0,-188,0,i%5===0?-175:-183);p.pop()}p.textAlign(p.CENTER,p.CENTER);p.textFont('Georgia');p.textSize(22);for(let i=0;i<12;i++){let a=i*p.TWO_PI/12-p.HALF_PI;p.text(roman[i],Math.cos(a)*157,Math.sin(a)*157);p.push();p.translate(Math.cos(a)*115,Math.sin(a)*115);gear(20,12,rot*(i%2?1:-1),2);p.pop()}for(const [x,y,rr,d] of [[-34,18,46,1],[43,23,35,-1],[3,-48,30,-1],[4,65,22,1]]){p.push();p.translate(x,y);gear(rr,20,rot*d,3);p.pop()}p.beginShape();for(let a=0;a<17;a+=.09){let rr=5+a*3.5;p.vertex(Math.cos(a+room.time*.02)*rr,Math.sin(a+room.time*.02)*rr)}p.endShape();hand(room.time/43200*p.TWO_PI+q.spin,110,8);hand(room.time/3600*p.TWO_PI+q.spin,165,5);p.push();p.rotate(room.time/60*p.TWO_PI+q.spin);p.line(0,28,0,-177);p.circle(0,22,12);p.pop();p.circle(0,0,12);p.pop()}
function backgroundArt(){field.loadPixels();const w=field.width,h=field.height,c=room.calm;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const u=x/w*2.8,v=y/w*2.8;let warp=p.noise(u*.75+t*.23,v*.75-t*.17),warp2=p.noise(u*.8+9-t*.18,v*.8+t*.21);let n=p.noise(u+warp*1.5,v+warp2*1.5,t*.3);let ribbon=Math.sin((n*7+u*.48-v*.2+t*.35+phase)*Math.PI);let darkness=Math.pow(Math.max(0,(ribbon-.08)/.92),2.2)*.92;let ordered=(bayer[(x%4)+(y%4)*4]+.5)/16;let grain=(Math.random()-.5)*.10;let ink=darkness+grain>ordered;let base=ink?26:251;let idx=(x+y*w)*4;let col=palette[Math.min(4,Math.floor(n*5))];for(let k=0;k<3;k++){let pastel=250-(255-col[k])*darkness*.9;field.pixels[idx+k]=base*(1-c)+pastel*c+(Math.random()-.5)*7*c}field.pixels[idx+3]=255}field.updatePixels();p.image(field,0,0,p.width,p.height)}
function cameraArt(){const canvas=el('camera-art'),ctx=canvas.getContext('2d'),video=el('video');if(video.readyState<2)return;ctx.save();ctx.translate(160,0);ctx.scale(-1,1);ctx.filter=room.running?'grayscale(1) contrast(.7)':'grayscale(1) blur(5px) contrast(1.8)';ctx.drawImage(video,0,0,160,110);ctx.restore();ctx.fillStyle='#faf8ee';for(let y=0;y<110;y+=4)for(let x=0;x<160;x+=4){ctx.beginPath();ctx.arc(x,y,room.running?.8:1.4,0,Math.PI*2);ctx.fill()}}
p.draw=()=>{let dt=Math.min(p.deltaTime/1000,.06);if(room.face!==room.running){room.running=room.face;room.rewind=room.running?1.5:0;if(room.running){tone(1046,.9,.12);setTimeout(()=>tone(1568,.7,.06),130)}else tone(230,.5,.1,45)}room.calm=p.lerp(room.calm,room.running?1:0,.025);if(room.rewind>0){room.rewind-=dt;room.time-=dt*8}else if(room.running)room.time+=dt;t+=dt*(room.gentle?.08:room.running?.65:1.4);if(p.frameCount%2===0)backgroundArt();else p.image(field,0,0,p.width,p.height);p.blendMode(p.DIFFERENCE);for(const q of parts)dial(q);p.blendMode(p.BLEND);cameraArt();let tick=Math.floor(room.time);if(room.running&&room.rewind<=0&&tick!==lastTick){tone(tick%2?850:650,.04,.035);lastTick=tick}if(audio){hiss.gain.setTargetAtTime(.15*(1-room.calm)+.015*room.calm,audio.currentTime,.2);filter.frequency.setTargetAtTime(1900*(1-room.calm)+240*room.calm,audio.currentTime,.2)}};
});


